UPDATE public.catalog_items SET needs_price_review = true, price_check_status = 'flagged', price_check_error = 'implausibly_low_for_model' WHERE title IS NOT NULL AND price_usd > 0 AND (needs_price_review IS NULL OR needs_price_review = false) AND ( (title ~* 'iphone\s*17\s*pro\s*max' AND ((title ~* '\m1\s*tb\M' AND price_usd < 1500) OR (title ~* '\m512\s*gb\M' AND price_usd < 1300) OR (title ~* '\m256\s*gb\M' AND price_usd < 1100) OR (title !~* '\m(1\s*tb|512\s*gb|256\s*gb)\M' AND price_usd < 1000))) OR (title ~* 'iphone\s*17\s*pro' AND title !~* 'max' AND ((title ~* '\m1\s*tb\M' AND price_usd < 1300) OR (title ~* '\m512\s*gb\M' AND price_usd < 1100) OR (title ~* '\m256\s*gb\M' AND price_usd < 900) OR (title !~* '\m(1\s*tb|512\s*gb|256\s*gb)\M' AND price_usd < 800))) OR (title ~* 'iphone\s*17' AND title !~* 'pro' AND ((title ~* '\m512\s*gb\M' AND price_usd < 850) OR (title ~* '\m256\s*gb\M' AND price_usd < 700) OR (title !~* '\m(512\s*gb|256\s*gb)\M' AND price_usd < 600))) OR (title ~* 'iphone\s*16\s*pro\s*max' AND ((title ~* '\m1\s*tb\M' AND price_usd < 1200) OR (title ~* '\m512\s*gb\M' AND price_usd < 1000) OR (title ~* '\m256\s*gb\M' AND price_usd < 850) OR (title !~* '\m(1\s*tb|512\s*gb|256\s*gb)\M' AND price_usd < 750))) OR (title ~* 'iphone\s*16\s*pro' AND title !~* 'max' AND price_usd < 600) OR (title ~* 'iphone\s*15\s*pro\s*max' AND price_usd < 600) OR (title ~* 'iphone\s*15\s*pro' AND title !~* 'max' AND price_usd < 500) OR (title ~* 'iphone\s*14\s*pro\s*max' AND price_usd < 500) OR (title ~* 'galaxy\s*s25\s*ultra' AND price_usd < 800) OR (title ~* 'galaxy\s*s24\s*ultra' AND price_usd < 650) );